/* Global styles for the Trip Expense Splitter app. */

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #f3f4f6;
  color: #111827;
  font-size: 15px;
  line-height: 1.5;
}

/* ── Layout ───────────────────────────────────────────────────────────── */

.app-header {
  background: #1d4ed8;
  color: #fff;
  padding: 0.875rem 1rem;
}
.app-header .inner {
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.app-header h1 { font-size: 1.15rem; font-weight: 700; }

.container {
  max-width: 760px;
  margin: 1.25rem auto;
  padding: 0 1rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* ── Card / Section ───────────────────────────────────────────────────── */

.card {
  background: #fff;
  border-radius: 8px;
  padding: 1.25rem;
  box-shadow: 0 1px 3px rgba(0,0,0,.1);
}
.card h2 {
  font-size: 1rem;
  font-weight: 600;
  color: #374151;
  margin-bottom: 1rem;
  padding-bottom: .5rem;
  border-bottom: 1px solid #e5e7eb;
}

/* ── Buttons ──────────────────────────────────────────────────────────── */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: .45rem .9rem;
  border: none;
  border-radius: 5px;
  font-size: .85rem;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: background .15s;
}
.btn:disabled { opacity: .5; cursor: not-allowed; }

.btn-primary   { background: #2563eb; color: #fff; }
.btn-primary:hover   { background: #1d4ed8; }

.btn-secondary { background: #6b7280; color: #fff; }
.btn-secondary:hover { background: #4b5563; }

.btn-danger    { background: #dc2626; color: #fff; }
.btn-danger:hover    { background: #b91c1c; }

.btn-ghost {
  background: transparent;
  color: #374151;
  border: 1px solid #d1d5db;
}
.btn-ghost:hover { background: #f9fafb; }

.btn-ghost-white {
  background: transparent;
  color: #fff;
  border: 1px solid rgba(255,255,255,.5);
}
.btn-ghost-white:hover { background: rgba(255,255,255,.15); }

.btn-sm { padding: .3rem .65rem; font-size: .8rem; }

/* ── Forms ────────────────────────────────────────────────────────────── */

.form-group {
  display: flex;
  flex-direction: column;
  gap: .3rem;
  margin-bottom: .75rem;
}
.form-group:last-child { margin-bottom: 0; }

label { font-size: .85rem; font-weight: 500; color: #374151; }

input[type="text"],
input[type="number"],
select {
  padding: .45rem .65rem;
  border: 1px solid #d1d5db;
  border-radius: 5px;
  font-size: .9rem;
  width: 100%;
  background: #fff;
}
input[type="text"]:focus,
input[type="number"]:focus,
select:focus {
  outline: 2px solid #3b82f6;
  outline-offset: 1px;
  border-color: #3b82f6;
}
input.field-error,
select.field-error { border-color: #ef4444; }

.field-error-msg {
  color: #dc2626;
  font-size: .8rem;
}

.form-row {
  display: flex;
  gap: .5rem;
  align-items: flex-end;
}
.form-row .form-group { flex: 1; margin-bottom: 0; }

.form-actions {
  display: flex;
  gap: .5rem;
  margin-top: .75rem;
}

/* Checkbox grid for sharer selection */
.checkbox-grid {
  display: flex;
  flex-wrap: wrap;
  gap: .4rem .75rem;
  margin-top: .25rem;
}
.checkbox-item {
  display: flex;
  align-items: center;
  gap: .3rem;
  font-size: .9rem;
}
.checkbox-item input { width: auto; }

/* Tip mode radio group */
.tip-modes {
  display: flex;
  gap: 1rem;
  margin-bottom: .5rem;
}
.tip-mode-opt {
  display: flex;
  align-items: center;
  gap: .3rem;
  font-size: .9rem;
  font-weight: 400;
  cursor: pointer;
}
.tip-mode-opt input { width: auto; }

/* ── Participant list ─────────────────────────────────────────────────── */

.participant-list { display: flex; flex-direction: column; gap: .5rem; }

.participant-row {
  display: flex;
  align-items: center;
  gap: .5rem;
  padding: .4rem 0;
  border-bottom: 1px solid #f3f4f6;
}
.participant-row:last-child { border-bottom: none; }

.participant-name { flex: 1; font-size: .95rem; }

.participant-actions { display: flex; gap: .4rem; flex-shrink: 0; }

.rename-form {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  gap: .4rem;
  align-items: flex-start;
}
.rename-form input { flex: 1; min-width: 120px; }

.inline-error {
  width: 100%;
  color: #dc2626;
  font-size: .8rem;
}

/* ── Expense list ─────────────────────────────────────────────────────── */

.expense-list { display: flex; flex-direction: column; gap: .75rem; }

.expense-item {
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  padding: .75rem .875rem;
}
.expense-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: .5rem;
}
.expense-title { font-weight: 600; font-size: .95rem; }
.expense-amount { font-weight: 700; color: #1d4ed8; white-space: nowrap; }
.expense-meta { font-size: .82rem; color: #6b7280; margin-top: .15rem; }
.expense-actions { display: flex; gap: .4rem; flex-shrink: 0; }

.rounding-note {
  font-size: .8rem;
  color: #6b7280;
  font-style: italic;
  margin-top: .35rem;
}

.delete-confirm {
  margin-top: .5rem;
  padding: .5rem .75rem;
  background: #fef2f2;
  border-radius: 5px;
  display: flex;
  align-items: center;
  gap: .75rem;
  font-size: .875rem;
  color: #7f1d1d;
}
.delete-confirm span { flex: 1; }

/* Expense list header row */
.expense-section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
}
.expense-section-header h2 { margin-bottom: 0; border-bottom: none; padding-bottom: 0; }

/* ── Settlement & Breakdown ───────────────────────────────────────────── */

.settlement-list { display: flex; flex-direction: column; gap: .4rem; }
.transfer-row {
  display: flex;
  align-items: center;
  padding: .4rem 0;
  border-bottom: 1px solid #f3f4f6;
  font-size: .925rem;
}
.transfer-row:last-child { border-bottom: none; }
.transfer-amount { font-weight: 700; margin-left: auto; color: #1d4ed8; }

.empty-state {
  color: #6b7280;
  font-size: .9rem;
  padding: .5rem 0;
}

.breakdown-list { display: flex; flex-direction: column; gap: 1rem; }

.breakdown-person {}
.breakdown-person-name {
  font-weight: 600;
  font-size: .95rem;
  margin-bottom: .4rem;
  padding-bottom: .25rem;
  border-bottom: 1px solid #f3f4f6;
}

.breakdown-table {
  width: 100%;
  font-size: .85rem;
  border-collapse: collapse;
}
.breakdown-table th {
  text-align: left;
  color: #6b7280;
  font-weight: 500;
  padding: .2rem .4rem .2rem 0;
}
.breakdown-table td {
  padding: .2rem .4rem .2rem 0;
  vertical-align: top;
}
.breakdown-table td.num { text-align: right; padding-right: .75rem; white-space: nowrap; }
.breakdown-table th.num { text-align: right; padding-right: .75rem; }

.breakdown-summary {
  margin-top: .4rem;
  font-size: .85rem;
  color: #374151;
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}
.net-positive { color: #166534; font-weight: 600; }
.net-negative { color: #991b1b; font-weight: 600; }
.net-zero     { color: #374151; }

/* ── Storage error banner ─────────────────────────────────────────────── */

.banner {
  padding: .75rem 1rem;
  border-radius: 6px;
  font-size: .875rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}
.banner-error {
  background: #fef2f2;
  border: 1px solid #fca5a5;
  color: #991b1b;
}

/* ── New trip modal ───────────────────────────────────────────────────── */

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
}
.modal {
  background: #fff;
  border-radius: 8px;
  padding: 1.5rem;
  max-width: 380px;
  width: 90%;
  box-shadow: 0 10px 30px rgba(0,0,0,.2);
}
.modal h3 { font-size: 1rem; margin-bottom: .5rem; }
.modal p { font-size: .9rem; color: #6b7280; margin-bottom: 1rem; }
.modal-actions { display: flex; gap: .5rem; justify-content: flex-end; }

/* ── Expense form panel ───────────────────────────────────────────────── */

.form-panel {
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  padding: 1rem;
  margin-bottom: .75rem;
}
.form-panel h3 { font-size: .95rem; font-weight: 600; margin-bottom: .75rem; }

