          <span style="align-self:center;color:#6b7280;font-size:.9rem">
            ${mode === "percent" ? "%" : "Rs."}
          </span>
        </div>
        ${f.errors.tip ? `<span class="field-error-msg">${escHtml(f.errors.tip)}</span>` : ""}
        ${f.errors.total ? `<span class="field-error-msg">${escHtml(f.errors.total)}</span>` : ""}
